def fibonacci(n):
    """Tính số Fibonacci thứ n bằng đệ quy (recursive)."""
    if n <= 0:
        return 0
    elif n == 1:
        return 1
    else:
        return fibonacci(n - 1) + fibonacci(n - 2)

# Ví dụ sử dụng
for i in range(11):
    print(f"F({i}) = {fibonacci(i)}")

